// Renders the raster icons that browsers without SVG favicon support still ask for,
// from public/favicon.svg: favicon.ico (16, 32 and 48 px) and apple-touch-icon.png
// (180 px, on a solid background because iOS rounds the corners itself).
// Run with `pnpm icons` after changing the mark; logo.svg carries the same mark inline
// and is regenerated by hand (see its comment).
import { readFile, writeFile } from 'node:fs/promises';
import sharp from 'sharp';

const svg = await readFile(new URL('../../public/favicon.svg', import.meta.url));
const render = (size, background) => {
  const image = sharp(svg, { density: (72 * size) / 64 }).resize(size, size);
  return (background ? image.flatten({ background }) : image).png().toBuffer();
};

// An .ico file is a 6-byte header, one 16-byte directory entry per image and then the
// images, which may be PNG data since Windows Vista.
const ico = (pngs) => {
  const header = Buffer.alloc(6);
  header.writeUInt16LE(0, 0);
  header.writeUInt16LE(1, 2);
  header.writeUInt16LE(pngs.length, 4);
  const entries = [];
  let offset = 6 + 16 * pngs.length;
  for (const { size, png } of pngs) {
    const entry = Buffer.alloc(16);
    entry.writeUInt8(size < 256 ? size : 0, 0);
    entry.writeUInt8(size < 256 ? size : 0, 1);
    entry.writeUInt8(0, 2);
    entry.writeUInt8(0, 3);
    entry.writeUInt16LE(1, 4);
    entry.writeUInt16LE(32, 6);
    entry.writeUInt32LE(png.length, 8);
    entry.writeUInt32LE(offset, 12);
    entries.push(entry);
    offset += png.length;
  }
  return Buffer.concat([header, ...entries, ...pngs.map((p) => p.png)]);
};

const sizes = [16, 32, 48];
const pngs = await Promise.all(sizes.map(async (size) => ({ size, png: await render(size) })));
await writeFile(new URL('../../public/favicon.ico', import.meta.url), ico(pngs));
await writeFile(new URL('../../public/apple-touch-icon.png', import.meta.url), await render(180, '#10162c'));
console.log('wrote public/favicon.ico and public/apple-touch-icon.png');
